import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute, Router } from '@angular/router';
import { OrdersService } from '../../services/orders.service';
import { CartService } from '../../services/cart.service';

@Component({
  standalone: true,
  selector: 'app-payment',
  imports: [CommonModule],
  templateUrl: './payment.component.html'
})
export class PaymentComponent implements OnInit {
  orderId!: number;
  orderStatus = 'PENDING_PAYMENT';
  message = '';
  loading = false;

  constructor(
    private route: ActivatedRoute,
    private orders: OrdersService,
    private router: Router,
    private cart: CartService
  ) {}

  ngOnInit() {
    // Get orderId from URL
    this.orderId = Number(this.route.snapshot.paramMap.get('orderId'));

    // If the page is loaded after Stripe redirect, fetch the order details
    this.fetchOrder();
  }

  fetchOrder() {
    this.orders.get(this.orderId).subscribe({
      next: (order) => {
        this.orderStatus = order.status;
        if (order.status === 'PAID') {
          this.message = 'Payment successful!';
          this.cart.clear(); // clear cart after successful payment
        }
      },
      error: (err) => {
        this.message = err?.error?.detail || 'Failed to fetch order';
      }
    });
  }

  payNow() {
    this.loading = true;

    // Step 1: create Stripe session
    this.orders.pay(this.orderId).subscribe({
      next: (res: any) => {
        // Step 2: redirect to Stripe checkout
        window.location.href = res.checkout_url;
      },
      error: (err) => {
        this.message = err?.error?.detail || 'Payment failed';
        this.loading = false;
      }
    });
  }

  goOrders() {
    this.router.navigateByUrl('/orders');
  }
}
